import Foundation

/// Mirrors `notification-categories.ts` in `@luki-fitti/common`. The checked-in
/// `Resources/notification_categories.json` fixture (regenerated by
/// `yarn notifications:export` in packages/common) is the shared truth —
/// `NotificationCategoriesPortTests` fails when the two drift apart.
public enum NotificationCategoryId: String, Codable, Sendable, Equatable, Hashable, CaseIterable {
    case friends
    case leagues
    case duels
    case streaks
    case raids
}

/// The `UserPreferences` boolean that gates every kind of a category.
public enum NotificationCategoryPref: String, Codable, Sendable, Equatable, Hashable {
    case pushFriends
    case pushLeagues
    case pushDuels
    case pushStreaks
    case pushRaids
}

public struct NotificationCategory: Sendable, Equatable {
    public let id: NotificationCategoryId
    public let pref: NotificationCategoryPref
    /// Kinds in enum order; every kind is in exactly one category.
    public let kinds: [SocialNotificationKind]
}

public enum NotificationCategories {
    /// Order is the display order on web and iOS: friends, leagues, duels,
    /// streaks, raids.
    public static let all: [NotificationCategory] = [
        NotificationCategory(
            id: .friends,
            pref: .pushFriends,
            kinds: [.FRIEND_REQUEST, .FRIEND_ACCEPTED]
        ),
        NotificationCategory(
            id: .leagues,
            pref: .pushLeagues,
            kinds: [.LEAGUE_PROMOTED, .LEAGUE_DEMOTED, .LEAGUE_ENDING]
        ),
        NotificationCategory(
            id: .duels,
            pref: .pushDuels,
            kinds: [.DUEL_INVITE, .DUEL_ACCEPTED, .DUEL_STANDINGS, .DUEL_RESULT]
        ),
        NotificationCategory(
            id: .streaks,
            pref: .pushStreaks,
            kinds: [.STREAK_INVITE, .STREAK_STARTED, .STREAK_REMINDER, .STREAK_FROZEN, .STREAK_BROKEN]
        ),
        NotificationCategory(
            id: .raids,
            pref: .pushRaids,
            kinds: [.RAID_SPAWNED, .RAID_PHASE, .RAID_DEFEATED, .RAID_ESCAPED, .SQUAD_INVITE, .SQUAD_RAID_STARTED]
        ),
    ]

    /// At most this many non-exempt social pushes per user per local delivery day.
    public static let dailyCap = 3

    /// Direct actions by a person — never count toward, and never blocked by,
    /// the daily cap.
    public static let capExemptKinds: Set<SocialNotificationKind> = [
        .FRIEND_REQUEST,
        .FRIEND_ACCEPTED,
        .DUEL_INVITE,
        .STREAK_INVITE,
        .SQUAD_INVITE,
    ]

    public static func category(of kind: SocialNotificationKind) -> NotificationCategory {
        for category in all where category.kinds.contains(kind) {
            return category
        }
        preconditionFailure("SocialNotificationKind \(kind) has no category")
    }
}
